7 🏢 Proveedores

7.1 Top 20 por número de contratos


Ver código
# Naranja MCCI para proveedores; nombres truncados a 45 chars para legibilidad
montos |&gt;
  mutate(
    proveedor = case_when(
      tipo_persona == "Moral"  ~ moral_razon_homo,
      tipo_persona == "Física" ~ nom_fisica_homo,
      TRUE ~ NA_character_
    )
  ) |&gt;
  filter(!is.na(proveedor)) |&gt;
  count(proveedor, sort = TRUE) |&gt;
  slice_max(n, n = 20) |&gt;
  mutate(proveedor = str_trunc(proveedor, 45),
         proveedor = fct_reorder(proveedor, n)) |&gt;
  ggplot(aes(x = n, y = proveedor)) +
  geom_col(fill = "#F26522", color = "#1A1A1A", linewidth = 0.25, alpha = 0.9) +
  geom_text(aes(label = n), hjust = -0.15, size = 3, color = "#1A1A1A") +
  scale_x_continuous(labels = label_comma(), expand = expansion(mult = c(0, 0.12))) +
  labs(title = "Top 20 proveedores por número de contratos",
       subtitle = "Posibles proveedores recurrentes — analizar concentración",
       x = "Número de contratos", y = NULL, caption = "Fuente: MCCI") +
  theme_minimal(base_size = 12) +
  theme(
    plot.title = element_text(color = "#0d1b2a", face = "bold"),
    plot.subtitle = element_text(color = "#64748b"),
    axis.text = element_text(color = "#1e293b", size = 9),
    panel.grid.major.y = element_blank()
  )








Figura 9: Top 20 proveedores por número de contratos







7.2 Top 15 por monto total


Ver código
# Rojo MCCI para top proveedores por monto — contraste alto en fondo blanco
montos |&gt;
  filter(costo &gt; 0) |&gt;
  mutate(
    proveedor = case_when(
      tipo_persona == "Moral"  ~ moral_razon_homo,
      tipo_persona == "Física" ~ nom_fisica_homo,
      TRUE ~ NA_character_
    )
  ) |&gt;
  filter(!is.na(proveedor)) |&gt;
  group_by(proveedor) |&gt;
  summarise(monto_total = sum(costo, na.rm = TRUE), .groups = "drop") |&gt;
  slice_max(monto_total, n = 15) |&gt;
  mutate(proveedor = str_trunc(proveedor, 45),
         proveedor = fct_reorder(proveedor, monto_total)) |&gt;
  ggplot(aes(x = monto_total, y = proveedor)) +
  geom_col(fill = "#E8001C", color = "#1A1A1A", linewidth = 0.25, alpha = 0.9) +
  scale_x_continuous(
    labels = label_dollar(scale = 1e-6, big.mark = ","),
    expand = expansion(mult = c(0, 0.05))
  ) +
  labs(title = "Top 15 proveedores por monto total contratado",
       subtitle = "Outliers de monto — posibles contratos de alto valor a revisar",
       x = "Monto total (millones MXN)", y = NULL, caption = "Fuente: MCCI") +
  theme_minimal(base_size = 12) +
  theme(
    plot.title = element_text(color = "#0d1b2a", face = "bold"),
    plot.subtitle = element_text(color = "#64748b"),
    axis.text = element_text(color = "#1e293b", size = 9),
    panel.grid.major.y = element_blank()
  )








Figura 10: Top 15 proveedores por monto total contratado

3 📊 Análisis exploratorio orientado a la pregunta
Antes de modelar, es útil observar si ya visualmente hay diferencias entre partidos en las variables que usaremos como predictores. Si no hay diferencias aparentes, el modelo tampoco las encontrará.

3.1 Gráfica 1 — Distribución del costo (log) por partido


Ver código
datos |&gt;
  filter(!is.na(partido)) |&gt;
  ggplot(aes(x = forzar_orden_partidos(partido), y = log_costo, fill = partido)) +
  geom_violin(alpha = 0.7) +
  geom_boxplot(width = 0.1, outlier.size = 0.5, fill = "white") +
  scale_fill_manual(values = paleta_partidos) +
  labs(
    title   = "Distribución del costo (log) por partido político",
    x       = NULL,
    y       = "log(costo + 1)",
    caption = "Fuente: MCCI"
  ) +
  theme_minimal() +
  theme(legend.position = "none")








Figura 1: Distribución del logaritmo del costo de contratos por partido político. Violín exterior muestra la densidad; boxplot interior muestra la mediana e IQR.







3.2 Gráfica 2 — Proporción de tipo de persona por partido


Ver código
datos |&gt;
  filter(!is.na(tipo_persona), !is.na(partido)) |&gt;
  count(partido, tipo_persona) |&gt;
  group_by(partido) |&gt;
  mutate(prop = n / sum(n)) |&gt;
  ungroup() |&gt;
  ggplot(aes(x = forzar_orden_partidos(partido), y = prop, fill = tipo_persona)) +
  geom_col(position = "fill", alpha = 0.85) +
  scale_y_continuous(labels = label_percent()) +
  scale_fill_manual(
    values = c("Moral" = "#003B8D", "Física" = "#CC6600"),
    name   = "Tipo de persona"
  ) +
  labs(
    title   = "Tipo de persona del proveedor por partido político",
    x       = "Partido",
    y       = "Proporción de contratos",
    caption = "Fuente: MCCI"
  ) +
  theme_minimal()








Figura 2: Proporción de contratos con persona física o moral por partido. Barras apiladas al 100%.







3.3 Gráfica 3 — Número mediano de contratos por proveedor según partido


Ver código
df_mediana &lt;- datos |&gt;
  filter(!is.na(partido)) |&gt;
  mutate(
    proveedor = case_when(
      tipo_persona == "Moral"  ~ moral_razon_homo,
      tipo_persona == "Física" ~ nom_fisica_homo,
      TRUE                     ~ NA_character_
    )
  ) |&gt;
  filter(!is.na(proveedor)) |&gt;
  group_by(partido, proveedor) |&gt;
  summarise(n_contratos = n(), .groups = "drop") |&gt;
  group_by(partido) |&gt;
  summarise(mediana_contratos = median(n_contratos), .groups = "drop") |&gt;
  mutate(
    partido = fct_reorder(partido, mediana_contratos),
    color   = paleta_partidos[as.character(partido)]
  )

p_mediana &lt;- df_mediana |&gt;
  ggplot(aes(
    x    = mediana_contratos,
    y    = partido,
    fill = partido,
    text = paste0("Partido: ", partido, "&lt;br&gt;Mediana: ", mediana_contratos)
  )) +
  geom_col(alpha = 0.88) +
  scale_fill_manual(values = paleta_partidos) +
  labs(
    title   = "Mediana de contratos por proveedor según partido",
    x       = "Mediana de contratos por proveedor",
    y       = NULL,
    caption = "Fuente: MCCI"
  ) +
  theme_minimal() +
  theme(legend.position = "none")

ggplotly(p_mediana, tooltip = "text") |&gt;
  layout(xaxis = list(title = "Mediana de contratos por proveedor"),
         yaxis = list(title = ""))








Figura 3: Número mediano de contratos obtenidos por proveedor, desagregado por partido que asigna.
